class TemporaryError(Exception):
    pass

class Gateway:
    def __init__(self, failures=()):
        self.failures = list(failures)
        self.calls = 0
        self.receipts = []

    def find(self, job_id):
        return next((r for r in self.receipts if r['job_id'] == job_id), None)

    def issue(self, job_id, amount):
        self.calls += 1
        failure = self.failures.pop(0) if self.failures else None
        if failure == 'before':
            raise TemporaryError('before write')
        receipt = {'number': len(self.receipts) + 1, 'job_id': job_id, 'amount': amount}
        self.receipts.append(receipt)
        if failure == 'after':
            raise TemporaryError('after write')
        return receipt

